import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { cacheReadInputTokensSchema, type CacheReadInputTokens } from "./unions/cache-read-input-tokens.js";

export type MessagesUsage = {
  /** Number of billed input tokens for this request. */
  inputTokens: number;
  /** Number of billed output tokens generated by the model. */
  outputTokens: number;
  /** Number of input tokens served from cache, when cache reads are applicable. */
  cacheReadInputTokens?: CacheReadInputTokens;
};

export const messagesUsageSchema: Schema<MessagesUsage> = s.object<MessagesUsage>({
  inputTokens: s.int(),
  outputTokens: s.int(),
  cacheReadInputTokens: s.optional(s.lazy(() => cacheReadInputTokensSchema)),
  _keysMap: {
    inputTokens: "input_tokens",
    outputTokens: "output_tokens",
    cacheReadInputTokens: "cache_read_input_tokens",
  },
});
